        if not bands or i != bands[-1][-1] + 1:
            bands.append([i])
        else:
            bands[-1].append(i)

    # Find the repeated rows in separate bands. Either copy may be incomplete,
    # so mark a row's trailing background only where its paired row has fg.
    if len(bands) >= 2:
        for bi in range(len(bands) // 2):
            first, last = bands[bi], bands[-1 - bi]
